#include <bits/stdc++.h>
using namespace std;
using ll=long long;
int main() {
	// your code goes here
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        vector<int> v(3*n);
        vector<ll> p(3*n+1);
        for(int i=0; i<3*n; i++){
            cin>>v[i];
        }
        sort(v.rbegin(),v.rend());
        for(int i=0; i<3*n; i++){
            p[i+1]=v[i]+p[i];
        }
        ll ans=0;
        auto cal=[&](int x,int y)->ll{
            int z=n-x-y;
            if(z<0){
                return -1;
            }
            return p[x]*6+(p[x+2*y]-p[x])*4+(p[x+2*y+3*z]-p[x+2*y])*3;  
        };
        for(int x=0; x<=n; x++){
            
                int l=0,r=n-x;
                while(l!=r){
                    int m=(l+r)/2;
                    if(cal(x,m)<=cal(x,m+1)){
                        l=m+1;
                    }
                    else {
                        r=m;
                    }
                }
                ans=max(ans,cal(x,l));
            
        }
        cout<<ans<<'\n';
    }
}
